package app.cryptoresearch.mobile;
import android.app.Activity;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import org.json.*;import java.util.concurrent.*;import java.nio.charset.StandardCharsets;import java.text.DateFormat;import java.util.Date;
/** Read-only operations. Credentials are loaded locally, never put in Intents. */
public class ServerOperationsActivity extends OneUiActivity {
 final Handler handler=new Handler(Looper.getMainLooper());final ExecutorService io=Executors.newSingleThreadExecutor();
 LinearLayout body,content;TextView message;String base="",secret="",nextBefore=null;boolean visible,busy;long generation;int tab;String sessionFilter="전체";
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(OneUi.ink(this));t.setPadding(0,dp(6),0,dp(6));return t;}
 LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(18),dp(16),dp(18),dp(16));GradientDrawable d=new GradientDrawable();d.setColor(OneUi.surface(this));d.setCornerRadius(dp(28));c.setBackground(d);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(14);content.addView(c,p);return c;}
 void button(LinearLayout c,String label,Runnable action){Button b=new Button(this);b.setText(label);OneUi.button(b);b.setOnClickListener(v->action.run());c.addView(b);}
 public void onCreate(Bundle saved){super.onCreate(saved);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(OneUi.horizontal(this)),dp(20),dp(OneUi.horizontal(this)),dp(20));body.setBackgroundColor(OneUi.bg(this));scroll.addView(body);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});scroll.requestApplyInsets();body.addView(OneUi.header(this,"서버 운영 센터","모의계좌와 운영 상태를 확인해요"));body.addView(text("모의매매 전용 · 조회 기능\n기록은 서버에 보관됩니다. 서버1.4 이상이 필요합니다.",13));button(body,"돌아가기",this::finish);
 LinearLayout tabs=new LinearLayout(this);tabs.setOrientation(LinearLayout.HORIZONTAL);body.addView(tabs);for(int i=0;i<3;i++){final int selected=i;Button b=new Button(this);b.setText(new String[]{"진단","운영 기록","이전 세션"}[i]);b.setOnClickListener(v->{generation++;busy=false;tab=selected;nextBefore=null;loadCurrent();});tabs.addView(b,new LinearLayout.LayoutParams(0,-2,1));}
 message=text("서버 설정을 저장한 뒤 새로고침하세요.",13);message.setTextIsSelectable(true);body.addView(message);button(body,"새로고침",()->{nextBefore=null;loadCurrent();});content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);body.addView(content);base=getSharedPreferences("paper-server",MODE_PRIVATE).getString("url","");try{secret=ServerVault.read(this);}catch(Exception ignored){}
 }
 void loadCurrent(){load(tab==0?"api/v1/diagnostics":tab==1?"api/v1/events?limit=50":"api/v1/sessions?limit=100");}
 void load(String path){if(busy||!visible)return;if(base.isEmpty()||secret.isEmpty()){message.setText("이전 화면에서 HTTPS 주소와 서버 토큰을 저장하세요.");return;}busy=true;long request=++generation;message.setText("서버 조회 중 · 이전 화면 내용은 최신 결과가 아닐 수 있습니다.");io.execute(()->{if(request!=generation||!visible)return;try{byte[] data=PaperServerAPI.request(base,secret,path,null);JSONObject json=new JSONObject(new String(data,StandardCharsets.UTF_8));handler.post(()->{if(request!=generation||!visible||isDestroyed())return;busy=false;try{render(path,json,data);message.setText("앱 수신 "+DateFormat.getDateTimeInstance().format(new Date())+" · 조회 당시 기록");}catch(Exception e){message.setText("응답 형식 확인 필요 · 새로고침하세요.");}});}catch(Exception e){handler.post(()->{if(request!=generation||!visible||isDestroyed())return;busy=false;message.setText("조회 실패 · "+e.getMessage()+"\n이전 표시가 남아 있다면 과거 수신 결과입니다.");});}});}
 void render(String path,JSONObject json,byte[] data)throws Exception {content.removeAllViews();if(path.endsWith("/report")){LinearLayout c=card();c.addView(text("이전 세션 · "+json.optString("session_symbol","—"),20));c.addView(text("잔여 모의 보유를 포함한 보관 리포트 · 현재 계좌와 별도",12));c.addView(new ResearchAnalyticsView(this,data));button(c,"서버 리포트 JSON 저장/공유",()->{try{ServerReportExport.share(this,data);}catch(Exception e){message.setText(e.getMessage());}});return;}
 if(path.equals("api/v1/diagnostics")){if(!"SERVER_PAPER_ONLY".equals(json.optString("mode"))||json.optBoolean("live_orders_supported",true))throw new Exception();LinearLayout c=card();c.addView(text("서버 "+json.optString("version","—"),21));c.addView(text("모의세션 "+state(json.optString("session_state"))+"\n가동 "+json.optDouble("uptime_seconds",0)+"초\n수신 프레임 "+json.optLong("feed_frames")+" · 재연결 "+json.optLong("feed_reconnects")+"\nDB 본체 "+json.optLong("database_bytes")/1024+"KB (WAL 제외)",15));JSONObject workers=json.optJSONObject("workers");if(workers!=null){java.util.Iterator<String> keys=workers.keys();while(keys.hasNext()){String k=keys.next();c.addView(text(k+" · "+state(workers.optString(k)),14));}}c.addView(text("횟수는 서버 재시작 때 초기화됩니다. 작업 중단 시 관리자 확인과 서버 재시작이 필요합니다. Gram 절전 시 서버도 멈춥니다.",12));return;}
 JSONArray items=json.optJSONArray("items");if(items==null)throw new Exception();if(items.length()==0)card().addView(text("아직 보관된 기록이 없습니다.",16));if(path.startsWith("api/v1/events")){for(int i=0;i<Math.min(50,items.length());i++){JSONObject j=items.getJSONObject(i);LinearLayout c=card();c.addView(text(event(j.optString("kind")),18));c.addView(text(DateFormat.getDateTimeInstance().format(new Date(j.optLong("created_ms")))+"\n"+j.optString("detail"),13));}String cursor=json.isNull("next_before")?null:json.optString("next_before",null);if(cursor!=null&&PaperServerAPI.allowedPath("api/v1/events?limit=50&before="+cursor)){nextBefore=cursor;button(content,"이전 기록 50개",()->load("api/v1/events?limit=50&before="+nextBefore));}}else{String[] filters={"전체","BTC","ETH","XRP","SOL","DOGE","ADA"};Spinner picker=new Spinner(this);picker.setContentDescription("이전 세션 종목 필터");picker.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,filters));picker.setSelection(java.util.Arrays.asList(filters).indexOf(sessionFilter));picker.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int position,long id){if(sessionFilter.equals(filters[position]))return;sessionFilter=filters[position];try{render(path,json,data);}catch(Exception e){message.setText("필터 표시 실패");}}});content.addView(picker);int displayed=0;for(int i=0;i<Math.min(100,items.length());i++){JSONObject j=items.getJSONObject(i);if(!sessionFilter.equals("전체")&&!sessionFilter.equals(j.optString("symbol")))continue;displayed++;String id=j.optString("session_id");LinearLayout c=card();c.addView(text(j.optString("symbol","—")+" · 보관된 모의계좌",18));c.addView(text(DateFormat.getDateTimeInstance().format(new Date((long)(j.optDouble("archived_at")*1000))),13));if(PaperServerAPI.allowedPath("api/v1/sessions/"+id+"/report"))button(c,"리포트 열기",()->load("api/v1/sessions/"+id+"/report"));}if(displayed==0&&items.length()>0)card().addView(text("선택 종목의 보관된 세션이 없습니다.",15));content.addView(text("표시 "+displayed+"개 · 서버에 보관된 최근100개까지 표시합니다. 새 모의세션 시작 시 직전 계좌가 보관됩니다.",12));}}
 static String state(String s){switch(s){case "running":return "실행 중";case "paused":return "정지";case "idle":return "대기";case "failed":return "작업 중단";default:return s;}}
 static String event(String s){switch(s){case "started":return "모의세션 시작";case "paused":return "모의세션 정지";case "restored":return "계좌 복원 · 정지 상태";case "feed_retry":return "시세 재연결";case "worker_failed":return "서버 작업 중단";default:return s;}}
 public void onStart(){super.onStart();visible=true;}
 public void onStop(){visible=false;generation++;busy=false;super.onStop();}
 public void onDestroy(){generation++;handler.removeCallbacksAndMessages(null);io.shutdownNow();super.onDestroy();}
}
